import assert from 'node:assert';
import { load, dump, YAML11_SCHEMA } from 'js-yaml';

describe('proof', () => {
  it('fails on the patched build', () => {
    // Signed binary integers must still resolve under the YAML 1.1 schema.
    assert.strictEqual(load('-0b101', { schema: YAML11_SCHEMA }), -5);
    assert.strictEqual(load('+0b101', { schema: YAML11_SCHEMA }), 5);
    // A decimal digit before 0b... is not a binary integer.
    assert.strictEqual(load('10b101', { schema: YAML11_SCHEMA }), '10b101');
    // DUMP_SCHEMA extends the YAML 1.1 schema, so this string must dump unquoted.
    assert.strictEqual(dump('10b101'), '10b101\n');
  });
});
"}, "note": "The diff changed the optional sign `[-+]?` of the YAML 1.1 binary-integer alternative into the negated class `[^-+]`: signed binary literals like `-0b101`/`+0b101` no longer resolve and load as strings under YAML11_SCHEMA, while garbage like `10b101` now matches and loads as the integer 10 (and dump quotes such strings as a result)."}
